export type Category = {
  slug: string;
  name: string;
  tagline: string;
  image: string;
};

export const categories: Category[] = [
  { slug: "books", name: "Books", tagline: "Medical · Law · Engineering · Sciences · Management · A-Levels · JAMB · WAEC", image: catBooks },
  { slug: "medical-equipment", name: "Medical Equipment", tagline: "Diagnostic & clinical tools", image: catMedical },
  { slug: "laboratory", name: "Laboratory Equipment", tagline: "Microscopes, glassware, reagents", image: catLab },
  { slug: "consumables", name: "Hospital Consumables", tagline: "PPE, syringes, dressings", image: catConsumables },
  { slug: "educational", name: "Educational Materials", tagline: "Stationery, learning aids", image: catEducation },
];

export type Product = {
  id: string;
  name: string;
  slug: string;
  category: string;
  image: string;
  description: string;
  features: string[];
  bestSeller?: boolean;
  price?: number;
  currency?: string;
  stock?: number;
  trackStock?: boolean;
};

export function formatPrice(amount: number, currency = "NGN") {
  try {
    return new Intl.NumberFormat("en-NG", { style: "currency", currency, maximumFractionDigits: 0 }).format(amount);
  } catch {
    return `${currency} ${amount.toLocaleString()}`;
  }
}

export function normalizeProductKey(value: string) {
  return value
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/\([^)]*\)/g, " ")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\b(the|a|an|and|with|for|of|in|edition|ed|international|student|students|global|classic|regional|approach|volume|vol|set|kit|machine)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function imageKey(image: string) {
  return image.split("?")[0] || image;
}

function productKeys(product: Product) {
  return [
    `slug:${product.slug.trim().toLowerCase()}`,
    `name:${normalizeProductKey(product.name)}`,
    product.image ? `image:${imageKey(product.image)}` : "",
  ].filter(Boolean);
}

export function dedupeProducts(list: Product[]) {
  const seen = new Set<string>();
  const out: Product[] = [];
  for (const product of list) {
    const keys = productKeys(product);
    if (keys.some((key) => seen.has(key))) continue;
    keys.forEach((key) => seen.add(key));
    out.push(product);
  }
  return out;
}

